import {Injectable} from '@angular/core';
import {environment} from '../../environments/environment';
import { HttpClient } from '@angular/common/http';
import {BehaviorSubject, firstValueFrom} from 'rxjs';
import * as jose from 'jose'
import {ConfigService, ResponseWrapper, SDKMode, VaultAuthFinishResponse} from '@shared-library';

export const FASTEN_AUTH_VAULT_COOKIE_NAME = 'fasten_connect_auth_vault'
export const VAULT_AUTH_COOKIE_RECHECK_DELAY_MS = 100

export enum CookieProbeScope {
  All = 'all',
  Regular = 'regular',
}

export interface VaultAuthCookieDebugInfo {
  cookieName: string
  isSet: boolean
  value: string
  valueLength: number
}

interface CookieSupportResponse {
  supported: boolean
}

interface CookieProbeResponse {
  probe: string
}

export interface VaultAuthCodeExpiry {
  expires: number
}

export type VaultAuthBeginResult = Partial<VaultAuthCodeExpiry & VaultAuthFinishResponse>

@Injectable({
  providedIn: 'root'
})
export class AuthService {

  public IsAuthenticatedSubject = new BehaviorSubject<boolean>(false)
  private cookieSupported?: boolean

  constructor(
    private _httpClient: HttpClient,
    private configService: ConfigService
  ) {}




  public async VaultAuthBegin(email: string, cspPromptForce?: boolean): Promise<VaultAuthBeginResult | undefined> {
    const resp = await this._httpClient.post<ResponseWrapper<VaultAuthCodeExpiry> | VaultAuthFinishResponse>(`${environment.connect_api_endpoint_base}/bridge/vault_auth_begin`, {
      "email": email,
      "csp_prompt_force": cspPromptForce,
    }, {withCredentials: true, params: {"public_id": this.configService.systemConfig$.publicId} }).toPromise()
    return resp && 'data' in resp ? resp.data : resp
  }

  public async VaultAuthFinish(email: string, code: string): Promise<any> {
    let resp = await this._httpClient.post(`${environment.connect_api_endpoint_base}/bridge/vault_auth_finish`, {
      "email": email,
      "code": code,
    }, { withCredentials: true, params: {"public_id": this.configService.systemConfig$.publicId} }).toPromise()
    return resp
  }

  public async VaultAuthResendCode(email: string): Promise<VaultAuthCodeExpiry | undefined> {
    const resp = await this._httpClient.post<ResponseWrapper<VaultAuthCodeExpiry>>(`${environment.connect_api_endpoint_base}/bridge/vault_auth_resend_code`, {
      "email": email,
    }, {withCredentials: true, params: {"public_id": this.configService.systemConfig$.publicId}}).toPromise()
    return resp?.data
  }

  public async Signout(): Promise<any> {
    this.publishAuthenticationState(false)
    return deleteCookie(FASTEN_AUTH_VAULT_COOKIE_NAME)
  }

  public IsVaultAuthCookieSet(): boolean {
    const isSet = this.GetVaultAuthCookieDebugInfo().isSet
    if (!isSet) {
      console.warn('[AuthService] Vault auth cookie is not set')
    }
    return isSet
  }

  public async WaitForVaultAuthCookie(): Promise<boolean> {
    if (this.IsVaultAuthCookieSet()) {
      return true
    }

    await new Promise<void>((resolve) => setTimeout(resolve, VAULT_AUTH_COOKIE_RECHECK_DELAY_MS))
    return this.IsVaultAuthCookieSet()
  }

  public async CheckCookieSupport(scope: CookieProbeScope = CookieProbeScope.All): Promise<boolean> {
    const scopeParams: Record<string, string> = {}
    if (scope === CookieProbeScope.Regular) {
      scopeParams['regular_only'] = 'true'
    }
    const expectedProbe = await this.setCookieProbe(scopeParams)
    const response = await firstValueFrom(this._httpClient.post<ResponseWrapper<CookieSupportResponse>>(
      `${environment.connect_api_endpoint_base}/bridge/cookie_support`, null, {
        withCredentials: true,
        params: {probe: expectedProbe, ...scopeParams},
      }
    ))
    const supported = response?.data?.supported

    if (typeof supported !== 'boolean') {
      throw new Error(`Invalid cookie support response: ${supported}`)
    }

    this.cookieSupported = supported
    return supported
  }

  private async setCookieProbe(params: Record<string, string>): Promise<string> {
    const response = await firstValueFrom(this._httpClient.post<ResponseWrapper<CookieProbeResponse>>(
      `${environment.connect_api_endpoint_base}/bridge/cookie_probe`, null, {
        withCredentials: true,
        params,
      }
    ))
    const probe = response?.data?.probe

    if (typeof probe !== 'string' || probe.length === 0) {
      throw new Error('Invalid cookie probe response')
    }

    return probe
  }

  public RequiresStorageAccessFallback(): boolean {
    return this.cookieSupported === false && this.CanUseStorageAccessFallback()
  }

  public CanUseStorageAccessFallback(): boolean {
    return this.configService.systemConfig$.sdkMode === SDKMode.None
      && typeof document.hasStorageAccess === 'function'
      && typeof document.requestStorageAccess === 'function'
  }

  public GetVaultAuthCookieDebugInfo(): VaultAuthCookieDebugInfo {
    const cookieValue = getCookie(FASTEN_AUTH_VAULT_COOKIE_NAME)
    const isSet = !!cookieValue

    return {
      cookieName: FASTEN_AUTH_VAULT_COOKIE_NAME,
      isSet,
      value: isSet ? '[REDACTED]' : '',
      valueLength: cookieValue.length,
    }
  }


  public async GetJWTPayload(): Promise<any> {
    let authToken = getCookie(FASTEN_AUTH_VAULT_COOKIE_NAME)
    if (!authToken) {
      return null
    }
    let jwks = jose.createRemoteJWKSet(new URL(environment.jwks_uri))
    let issuerHost = environment.connect_api_jwt_issuer_host

    try {
      //audience and issuer must be the same. This token is only valid on the fasten connect api
      const {payload, protectedHeader} = await jose.jwtVerify(authToken, jwks, {
        issuer: issuerHost,
        audience: issuerHost,
      })

      //TODO: check that the token is not expired
      // @ts-ignore
      this.configService.systemConfig = {user: payload}
      return payload
    } catch (e) {
      console.error("failed to verify jwt:", e, issuerHost)
      return null
    }
  }

  public async IsAuthenticated(): Promise<boolean> {
    let payload = await this.GetJWTPayload()
    let isAuthenticated = payload != null
    this.publishAuthenticationState(isAuthenticated)
    return isAuthenticated
  }

  /////////////////////////////////////////////////////////////////////////////////////////////////
  //Private Methods
  /////////////////////////////////////////////////////////////////////////////////////////////////

  private publishAuthenticationState(authenticated: boolean){
    if(this.IsAuthenticatedSubject.value != authenticated){
      this.IsAuthenticatedSubject.next(authenticated)
    }
  }
}


//https://stackoverflow.com/questions/34298133/angular-cookies
export function getCookie(name: string): string {
  const ca: Array<string> = document.cookie.split(';');
  const caLen: number = ca.length;
  const cookieName = `${name}=`;
  let c: string;

  for (let i  = 0; i < caLen; i += 1) {
    c = ca[i].replace(/^\s+/g, '');
    if (c.indexOf(cookieName) === 0) {
      const value = c.substring(cookieName.length, c.length)
      try {
        return decodeURIComponent(value)
      } catch {
        return value
      }
    }
  }
  return '';
}

export function setCookie(name: string, value: string, expireDays: number, path: string = '') {
  const d: Date = new Date();
  d.setTime(d.getTime() + expireDays * 24 * 60 * 60 * 1000);
  const expires = `expires=${d.toUTCString()}`;
  const cpath = path ? `; path=${path}` : '';
  document.cookie = `${name}=${value}; ${expires}${cpath}; SameSite=Lax`;
}

export function deleteCookie(name: string): Promise<void> {
  const baseCookie = `${name}=; Max-Age=0; expires=Thu, 01 Jan 1970 00:00:00 GMT; path=/`
  const domains = ['', `; Domain=${environment.connect_base_domain}`]

  for (const domain of domains) {
    document.cookie = `${baseCookie}${domain}; SameSite=Lax`
    document.cookie = `${baseCookie}${domain}; SameSite=None; Secure`
    document.cookie = `${baseCookie}${domain}; SameSite=None; Secure; Partitioned`
  }

  return Promise.resolve()
}
