import {Injectable, OnDestroy} from '@angular/core';
import * as Sentry from '@sentry/angular';
import {
  CallbackPayload,
  ConfigService,
  ConnectPayload,
  EventTypes,
  MessageBusEventPayload,
  MessageBusService,
  Organization,
} from '@shared-library';
import {Subscription} from 'rxjs';
import {FastenService} from './fasten.service';

const PUBLIC_ID_TAG = 'org.public_id';
const ORG_ID_TAG = 'org.id';
const ORG_NAME_TAG = 'org.name';
const ORG_PLAN_TAG = 'org.plan';
const ORG_FEATURE_FLAGS_TAG = 'org.feature_flags';
const REQUEST_ID_TAG = 'request_id';
const CONNECTION_ID_TAG = 'org_connection.id';

@Injectable({
  providedIn: 'root',
})
export class SentryContextService implements OnDestroy {
  private readonly subscriptions = new Subscription();

  constructor(
    private readonly configService: ConfigService,
    private readonly messageBusService: MessageBusService,
    private readonly fastenService: FastenService,
  ) {
    this.setIdentifier(
      PUBLIC_ID_TAG,
      new URLSearchParams(window.location.search).get('public-id') || undefined,
    );

    this.subscriptions.add(
      this.configService.systemConfigSubject.subscribe((config) => {
        if (config.publicId) {
          this.setIdentifier(PUBLIC_ID_TAG, config.publicId);
        }

        if (config.reconnectOrgConnectionId) {
          this.setIdentifier(CONNECTION_ID_TAG, config.reconnectOrgConnectionId);
        }
      }),
    );

    this.subscriptions.add(
      this.messageBusService.messageBusSubject.subscribe((event) => this.updateConnectionContext(event)),
    );

    this.subscriptions.add(
      this.fastenService.orgConfigLoadedSubject.subscribe((org) => this.updateOrganizationContext(org)),
    );
  }

  ngOnDestroy(): void {
    this.subscriptions.unsubscribe();
  }

  setConnectionContext(requestId?: string, connectionId?: string): void {
    this.setIdentifier(REQUEST_ID_TAG, requestId);
    this.setIdentifier(CONNECTION_ID_TAG, connectionId);
  }

  private updateOrganizationContext(org: Organization): void {
    this.setIdentifier(ORG_ID_TAG, org.id);
    this.setIdentifier(ORG_NAME_TAG, org.name);
    this.setIdentifier(ORG_PLAN_TAG, org.plan);
    this.setIdentifier(ORG_FEATURE_FLAGS_TAG, JSON.stringify(org.feature_flags ?? []));
  }

  private updateConnectionContext(event: MessageBusEventPayload | null): void {
    if (!event || Array.isArray(event.data)) {
      return;
    }

    if (event.event_type === EventTypes.EventTypeConnectionPending) {
      const connectData = event.data as ConnectPayload;
      this.setConnectionContext(undefined, connectData.org_connection_id);
      return;
    }

    if (
      event.event_type === EventTypes.EventTypeConnectionSuccess ||
      event.event_type === EventTypes.EventTypeConnectionFailed
    ) {
      const callbackData = event.data as CallbackPayload;
      this.setConnectionContext(callbackData.request_id, callbackData.org_connection_id);
    }
  }

  private setIdentifier(tag: string, value?: string): void {
    const normalizedValue = value || undefined;

    // Tags make the identifiers searchable on events. Scope attributes also
    // propagate them to Sentry logs and spans.
    Sentry.setTag(tag, normalizedValue);
    Sentry.getIsolationScope().setAttribute(tag, normalizedValue);
    Sentry.getActiveSpan()?.setAttribute(tag, normalizedValue);
  }
}
