import { Component, EnvironmentInjector, OnInit} from '@angular/core';
import {Router, RouterModule} from '@angular/router';
import {
  AddressInformation,
  CallbackPayload,
  ConfigService, CspType,
  ImageFallbackDirective,
  LighthouseBrandListDisplayItem,
  LighthouseEndpointListDisplayItem,
  LighthousePortalListDisplayItem,
  MessageBusService,
  RecordLocatorResponse,
  ResponseWrapper,
  StoreRecordLocatorResultsInVaultProfile,
  SourceCredentialType,
  VaultProfileConfig,
  PatientDemographics,
  ProcessTefcaDirectAuthorizationResults,
  formatPatientDemographicsAddress,
  formatPatientDemographicsBirthdate,
  formatPatientDemographicsName,
} from '@shared-library';
import {NGXLogger} from 'ngx-logger';
import {FastenService} from "../../services/fasten.service";
import {of, switchMap} from "rxjs";
import {CommonModule} from "@angular/common";
import {HeaderComponent} from "../../components/header/header.component";
import {SpinnerComponent} from "../../components/spinner/spinner.component";

@Component({
    selector: 'app-dashboard',
    templateUrl: './dashboard.component.html',
    styleUrls: ['./dashboard.component.css'],
    standalone: true,
    imports: [
      CommonModule, // Not needed if you don't use any common directives
      RouterModule,
      ImageFallbackDirective,
      HeaderComponent, // If you have a header component
      SpinnerComponent,
    ]
})
export class DashboardComponent implements OnInit {

  loadingTefcaRLS: boolean = false;
  emptyTefcaRLSResult: boolean = false;
  isCompleting: boolean = false;
  showPatientDemographicsPopover: boolean = false;
  patientAddressIndex: number = 0;

  constructor(
    public configService: ConfigService,
    private router: Router,
    private fastenService: FastenService,
    private messageBus: MessageBusService,
    private logger: NGXLogger,
    private injector: EnvironmentInjector,
  ) { }

  ngOnInit(): void {
    if (this.configService.systemConfig$.tefcaMode && !this.configService.vaultProfileConfig$.rlsQueryComplete) {
      this.loadingTefcaRLS = true;
      this.fastenService.recordLocatorRegisterAndPollForStatus().pipe(
        switchMap((rlsStatusResponse: ResponseWrapper) => {
          if(rlsStatusResponse.data.status == 'success') {
            console.log("RLS status response", rlsStatusResponse)
            return this.fastenService.recordLocatorResults(rlsStatusResponse.data.task_id)
          } else {
            console.error("RLS status response was not successful", rlsStatusResponse)
            return of(new RecordLocatorResponse())
          }
        })
      ).subscribe((rlsResponse: RecordLocatorResponse) => {
          console.log("record locator response", rlsResponse)
          const {numDiscovered, numPending, numConnected} = StoreRecordLocatorResultsInVaultProfile(this.configService, rlsResponse);

          this.loadingTefcaRLS = false
          this.configService.vaultProfileConfig = {
            rlsQueryComplete: true
          }
          this.emptyTefcaRLSResult = (numDiscovered + numPending + numConnected) == 0
      },
      (err) => {
          this.loadingTefcaRLS = false
          //TODO: write an error message to the user.
          console.error("Error fetching RLS data", err)
          this.configService.vaultProfileConfig = {
            rlsQueryComplete: true
          }
          this.emptyTefcaRLSResult = true
        }
      )
    }
  }

  connectAccount(externalState:string, pendingAccount: { brand: LighthouseBrandListDisplayItem, portal: LighthousePortalListDisplayItem, endpoint: LighthouseEndpointListDisplayItem, vault_profile_connection_id?: string }){
    this.logger.info("connecting account", pendingAccount)
    this.router.navigate(['dashboard/connecting'], {
      queryParams: {
        "brandId": pendingAccount.brand?.id,
        "portalId": pendingAccount.portal?.id,
        "endpointId": pendingAccount.endpoint?.id,
        "externalId": this.configService.systemConfig$.externalId,
        "externalState": externalState,
        "vaultProfileConnectionId": pendingAccount.vault_profile_connection_id
      }
    })
  }

  // Add patientAuthorizationType and this will basically be in the backend SourceCredentialType
  connectTefcaDirectAccount(externalState:string, pendingAccount: { brand: LighthouseBrandListDisplayItem, portal: LighthousePortalListDisplayItem, endpoint: LighthouseEndpointListDisplayItem, vault_profile_connection_id?: string, patient_auth_type?: SourceCredentialType }){
    this.configService.vaultProfileAddConnectedAccount(
     {
        external_state: externalState,
        org_connection_id: "",
        connection_status: "connected",
        platform_type: "tefca",
        brand_id: pendingAccount.brand?.id,
        portal_id: pendingAccount.portal?.id,
        endpoint_id: pendingAccount.endpoint?.id,
        vault_profile_connection_id: pendingAccount.vault_profile_connection_id,
        patient_auth_type: pendingAccount.patient_auth_type || SourceCredentialType.SourceCredentialTypeTefcaDirect
     } as CallbackPayload
   )
  }

  completeAccounts(){
    const connectedAccounts = (this.configService.vaultProfileConfig$.connectedPatientAccounts || []);
    const tefcaDirectAccounts = connectedAccounts.filter(
      (acc) => {
        // Only process TEFCA Direct & Network Direct accounts that lack an org_connection_id
        return !acc.org_connection_id && (
          acc.patient_auth_type === SourceCredentialType.SourceCredentialTypeTefcaDirect ||
          acc.patient_auth_type === SourceCredentialType.SourceCredentialTypeMedicareDirect
        )
      }
    );

    this.logger.debug(`Direct connected accounts to complete:`, tefcaDirectAccounts);
    // Grab vault connection IDs (required by backend). Dedupe on frontend; backend also dedupes as a safety net.
    const vaultConnectionIds = tefcaDirectAccounts
      .map(a => a.vault_profile_connection_id)
      .filter((id): id is string => !!id);
    const uniqueVaultConnectionIds = Array.from(new Set(vaultConnectionIds));

    if (uniqueVaultConnectionIds.length === 0) {
      this.router.navigateByUrl('dashboard/complete');
      return;
    }

    // show button-specific loader rather than banner
    // keep banner spinner only for RLS background fetches
    this.isCompleting = true;

    this.fastenService.authorizeTefcaDirect(uniqueVaultConnectionIds, this.configService.systemConfig$.externalId).subscribe(
      (resp) => {
        this.logger.info('Direct authorization response', resp);
        this.injector.runInContext(() => {
          ProcessTefcaDirectAuthorizationResults(uniqueVaultConnectionIds, resp);
        });
        this.isCompleting = false;
        this.router.navigateByUrl('dashboard/complete');
      },
      (err) => {
        this.logger.error('Failed to authorize Direct accounts', err);
        this.injector.runInContext(() => {
          ProcessTefcaDirectAuthorizationResults(uniqueVaultConnectionIds, null);
        });
        this.isCompleting = false;
        this.router.navigateByUrl('dashboard/complete');
      }
    );
  }


  //TODO1: add helper to process individual success, failure and catastrophic failures from aturhoizeTefcaDirect, and send messageBus events
  //TODO2: promote pending connections to connected list, so they will be sent to the customer via the Completed event.



  closeModal() {
    this.messageBus.publishRequestClose()
  }

  shouldShowMultiConnectHint(vaultProfile?: VaultProfileConfig | null): boolean {
    if (!vaultProfile) {
      return false
    }

    const pendingCount = Object.keys(vaultProfile.pendingPatientAccounts || {}).length
    const discoveredCount = Object.keys(vaultProfile.discoveredPatientAccounts || {}).length
    const connectedCount = vaultProfile.connectedPatientAccounts?.length ?? 0

    const firstPendingQueued = pendingCount === 1 && connectedCount === 0 && discoveredCount === 0
    const onlyOneConnected = connectedCount === 1 && pendingCount === 0 && discoveredCount === 0

    return firstPendingQueued || onlyOneConnected
  }

  protected readonly CspType = CspType;

  togglePatientDemographicsPopover(): void {
    this.showPatientDemographicsPopover = !this.showPatientDemographicsPopover;
  }

  getVerifiedPatientName(demographics?: PatientDemographics | null): string {
    return formatPatientDemographicsName(demographics);
  }

  getVerifiedPatientAddress(address?: AddressInformation | null): string {
    return formatPatientDemographicsAddress(address);
  }

  getPatientAddressCount(demographics?: PatientDemographics | null): number {
    return demographics?.addressInformation?.length || 0;
  }

  getCurrentPatientAddressNumber(demographics?: PatientDemographics | null): number {
    const addressCount = this.getPatientAddressCount(demographics);
    return addressCount ? (this.patientAddressIndex % addressCount) + 1 : 0;
  }

  showNextPatientAddress(demographics?: PatientDemographics | null): void {
    const addressCount = this.getPatientAddressCount(demographics);
    if (addressCount > 1) {
      this.patientAddressIndex = (this.patientAddressIndex + 1) % addressCount;
    }
  }

  getVerifiedBirthdate(demographics?: PatientDemographics | null): string {
    return formatPatientDemographicsBirthdate(demographics);
  }
}
