import {Component, Input, OnDestroy, OnInit} from '@angular/core';
import {AuthService} from '../../services/auth.service';
import {Router, RouterModule} from '@angular/router';
import {FastenService} from '../../services/fasten.service';
import {ConfigService} from '@shared-library';
import { Output, EventEmitter } from '@angular/core';
import {CommonModule} from "@angular/common";
import {logoText as sharedLogoText} from '../../utils/logo-text';

@Component({
    selector: 'app-header',
    templateUrl: './header.component.html',
    styleUrls: ['./header.component.css'],
    standalone: true,
    imports: [CommonModule, RouterModule]
})
export class HeaderComponent implements OnInit {
  readonly logoText = sharedLogoText

  @Input() backButtonLink: string = ''
  @Output() backButtonEvent = new EventEmitter<Event>();

  @Input() showClose: Boolean = false
  @Output() closeButtonEvent = new EventEmitter<Event>();


  constructor() { }

  ngOnInit() {}

  backButtonClick(e: Event) {
    console.log("header: back button clicked")
    this.backButtonEvent.emit(e);
  }

  closeButtonClick(e: Event) {
    console.log("header: close button clicked")
    this.closeButtonEvent.emit(e);
    // (e.target as HTMLElement).closest('.dropdown')?.classList.remove('show');
    // (e.target as HTMLElement).closest('.dropdown .dropdown-menu')?.classList.remove('show');
  }
}
