import {Component, EnvironmentInjector, Input, OnDestroy, OnInit} from '@angular/core';
import {Router, RouterModule} from '@angular/router';
import {ConnectHelper} from '../../utils/connect-helper';
import {ConfigService, ImageFallbackDirective, MessageBusService, SDKMode} from '@shared-library';
import {CommonModule} from "@angular/common";
import {HeaderComponent} from "../../components/header/header.component";
import {Subscription} from "rxjs";

@Component({
    selector: 'app-health-system-connecting',
    templateUrl: './health-system-connecting.component.html',
    styleUrls: ['./health-system-connecting.component.css'],
    standalone: true,
    imports: [
      CommonModule,
      RouterModule,
      HeaderComponent,
      ImageFallbackDirective
    ]
})
export class HealthSystemConnectingComponent implements OnInit, OnDestroy {
  @Input() brandId: string = "";
  @Input() portalId: string = "";
  @Input() endpointId: string = "";

  @Input() externalId?: string = "";
  @Input() externalState?: string = "";

  @Input() orgConnectionId?: string = ""; //required if reconnecting an existing source
  @Input() vaultProfileConnectionId?: string = ""; //required if reconnecting an existing vault profile connection id

  @Input() sdkMode?: SDKMode = SDKMode.None; //default is SDKMode.None, can be set to SDKMode.ReactNative or others

  private connectHelperSubscription: Subscription;

  constructor(
    public configService: ConfigService,
    private router: Router,
    private messageBus: MessageBusService,
    private injector: EnvironmentInjector
  ){}

  ngOnDestroy() {
    //this is required because in websocket mode, this subscription remains active until unsubscribed.
    if(this.connectHelperSubscription){
      this.connectHelperSubscription.unsubscribe();
    }
  }

  ngOnInit(): void {

    this.injector.runInContext(() => {
      this.connectHelperSubscription = ConnectHelper({
        public_id: this.configService.systemConfig$.publicId,
        brand_id: this.brandId,
        portal_id: this.portalId,
        endpoint_id: this.endpointId,
        org_connection_id: this.orgConnectionId,
        external_id: this.externalId,
        external_state: this.externalState,
        vault_profile_connection_id: this.vaultProfileConnectionId,
        connect_mode: this.configService.systemConfig$.connectMode,
      })
    })
  }

  cancelAccountConnect(){
    console.log("cancel account connect")
    // this.router.navigateByUrl('dashboard')
  }

  //close modal will only be visible when reconnecting.
  closeModal() {
    this.messageBus.publishRequestClose()
  }
}
